<?php

namespace Detain\Sshwitch;

use BadMethodCallException;

/**
 * Sshwitch — Login and run commands on network devices via SSH + RANCID's `clogin`.
 *
 * The class is fully static: state lives in static properties and every operation
 * is exposed through static methods. Setters and getters are auto-generated by
 * {@see Sshwitch::__callStatic()} so callers can do `Sshwitch::setTimeout(15)`
 * without those methods being defined explicitly.
 *
 * **Static chaining** — when {@see Sshwitch::$chaining} is true, every method
 * (including auto-generated setters) returns the class name string instead of
 * its natural return value, so calls can be composed PHP-style:
 *
 * ```php
 * Sshwitch::setChaining(true)::setTimeout(15)::run('10.0.0.1', 'show version');
 * $output = Sshwitch::setChaining(false)::getOutput();
 * ```
 *
 * **Required constants** — callers must `define()` these before calling
 * {@see Sshwitch::connect()} or {@see Sshwitch::run()}:
 *
 * - `CLOGIN_SSH_HOST` — IP/hostname of the relay box that holds `clogin`
 * - `CLOGIN_SSH_PORT` — SSH port on that relay (typically 22)
 * - `CLOGIN_SSH_USER` — SSH username on that relay
 * - `CLOGIN_SSH_KEY`  — Path to the SSH private key (the `.pub` sibling must exist)
 *
 * @package Detain\Sshwitch
 * @author  Joe Huss <detain@interserver.net>
 * @license GPL-3.0
 *
 * @method static resource|false getConnection()    Returns the current SSH connection resource (or false).
 * @method static int    getTimeout()               Returns the per-command timeout in seconds.
 * @method static string getSwitch()                Returns the last switch hostname/IP passed to run().
 * @method static array  getCommands()              Returns the last command list passed to run().
 * @method static string getOutput()                Returns the raw SSH output captured by the last run().
 * @method static string getHostname()              Returns the hostname parsed out of the device's `show hostname` reply.
 * @method static string getMotd()                  Returns the captured MOTD (banner) text, if any.
 * @method static array  getCommandOutputs()        Returns the parsed per-command output array.
 * @method static bool   getAutoDisconnect()        Returns whether run() will disconnect on completion.
 * @method static bool   getChaining()              Returns whether static chaining mode is active.
 * @method static string|bool setConnection($value)         Sets the SSH connection resource.
 * @method static string|bool setTimeout(int $value)        Sets the per-command timeout (seconds).
 * @method static string|bool setSwitch(string $value)      Sets the target switch hostname/IP.
 * @method static string|bool setCommands(array $value)     Sets the command list.
 * @method static string|bool setOutput(string $value)      Sets the raw output buffer (mostly used in tests).
 * @method static string|bool setHostname(string $value)    Sets the parsed hostname.
 * @method static string|bool setMotd(string $value)        Sets the MOTD buffer.
 * @method static string|bool setCommandOutputs(array $value) Sets the parsed per-command output array.
 * @method static string|bool setAutoDisconnect(bool $value) Toggles auto-disconnect after run().
 * @method static string|bool setChaining(bool $value)      Toggles static-chaining mode.
 */
class Sshwitch
{
    /**
     * Active SSH2 connection resource, or false when not connected.
     *
     * @var resource|false
     */
    public static $connection = false;

    /**
     * Per-command timeout (in seconds) handed to RANCID's `clogin -t` flag.
     *
     * @var int
     */
    public static int $timeout = 10;

    /**
     * Target device hostname or IP for the most recent {@see Sshwitch::run()} call.
     *
     * @var string
     */
    public static string $switch = '';

    /**
     * List of commands to run on the target device. May be supplied as a string
     * (semicolon-separated) to {@see Sshwitch::run()}; it is normalized to an array.
     *
     * @var array<int, string>
     */
    public static array $commands = [];

    /**
     * Raw output captured from the SSH stream during the last {@see Sshwitch::run()}.
     *
     * @var string
     */
    public static string $output = '';

    /**
     * Hostname parsed out of the device's response to the prepended `show hostname`
     * command (everything before the first dot — the bare short name).
     *
     * @var string
     */
    public static string $hostname = '';

    /**
     * Captured MOTD/banner text. Reserved for future use.
     *
     * @var string
     */
    public static string $motd = '';

    /**
     * Parsed per-command outputs, in the same order as {@see Sshwitch::$commands}
     * (after `show hostname` is stripped).
     *
     * @var array<int, string>
     */
    public static array $commandOutputs = [];

    /**
     * When true, {@see Sshwitch::run()} disconnects automatically after capturing
     * output. Disable to keep the connection open across multiple run() calls.
     *
     * @var bool
     */
    public static bool $autoDisconnect = true;

    /**
     * When true, methods return the class name (string) instead of their natural
     * return value, enabling PHP `::` chaining.
     *
     * @var bool
     */
    public static bool $chaining = false;

    /**
     * Establishes an SSH connection to the relay box defined by `CLOGIN_SSH_*`
     * constants and authenticates using the configured public key.
     *
     * Idempotent — does nothing if a connection is already open.
     *
     * @return string|bool When chaining is enabled, returns the class name. Otherwise
     *                     returns true on success and false on failure.
     */
    public static function connect()
    {
        if (!self::$connection) {
            self::$connection = ssh2_connect(CLOGIN_SSH_HOST, CLOGIN_SSH_PORT, ['hostkey' => 'ssh-rsa']);
            if (!self::$connection) {
                self::log('debug', 'sshwitch ssh returned connection:' . var_export(self::$connection, true));
                self::$connection = false;
                return self::$chaining ? self::class : false;
            }
            if (!ssh2_auth_pubkey_file(self::$connection, CLOGIN_SSH_USER, CLOGIN_SSH_KEY.'.pub', CLOGIN_SSH_KEY)) {
                self::log('debug', 'sshwitch ssh pubkey authentication failed:' . var_export(self::$connection, true));
                self::disconnect();
                return self::$chaining ? self::class : false;
            }
        }
        return self::$chaining ? self::class : true;
    }

    /**
     * Disconnects the current SSH connection, if any, and clears the connection
     * handle. Safe to call when no connection is open — it becomes a no-op.
     *
     * @return string|bool When chaining is enabled, returns the class name. Otherwise
     *                     returns the result of `ssh2_disconnect()` (true) when a
     *                     connection was actually closed, or true when there was
     *                     nothing to close.
     */
    public static function disconnect()
    {
        $return = true;
        if (self::$connection) {
            $return = ssh2_disconnect(self::$connection);
        }
        self::$connection = false;
        return self::$chaining ? self::class : $return;
    }

    /**
     * Runs a list of commands on the target switch via RANCID's `clogin`.
     *
     * The method:
     *  1. Connects to the relay (if not already connected).
     *  2. Prepends `show hostname` so the response can be parsed reliably.
     *  3. Builds and runs the `clogin` invocation through `ssh2_exec()`.
     *  4. Parses each command's output out of the combined stream using a
     *     regex anchored on the device hostname prompt.
     *  5. Disconnects when {@see Sshwitch::$autoDisconnect} is true.
     *
     * Long progress bars (e.g. `[######]  N%`) emitted by IOS during file
     * transfers are collapsed to just the final entry to keep logs readable.
     *
     * @param string                       $switch   Hostname or IP of the device.
     * @param string|array<int, string>    $commands Single command, semicolon-separated
     *                                               string, or array of commands.
     * @param string                       $type     Reserved — device family hint (cisco,
     *                                               juniper, …). Currently unused but
     *                                               kept so future overloads can branch
     *                                               on it without a signature change.
     * @param array<int, string>          &$return   Receives the parsed per-command
     *                                               output by reference.
     *
     * @return string|array<int, string>|false When chaining is enabled, returns the
     *                                         class name. Otherwise returns the parsed
     *                                         output array, or false on failure.
     */
    public static function run(string $switch, $commands, string $type = 'cisco', array &$return = [])
    {
        unset($type); // currently unused; kept in signature for forward-compat
        self::$switch = $switch;
        if (!is_array($commands)) {
            $commands = explode(';', $commands);
        }
        self::$commands = $commands;
        if (self::connect() === false && !self::$connection) {
            return self::$chaining ? self::class : false;
        }
        if (!self::$connection) {
            return self::$chaining ? self::class : false;
        }
        array_unshift(self::$commands, 'show hostname');
        $cmd = '/usr/libexec/rancid/clogin -autoenable -t '.self::$timeout.' -c '.escapeshellarg(implode(';', self::$commands)).' '.escapeshellarg($switch);
        $stream = ssh2_exec(self::$connection, $cmd);
        if ($stream === false) {
            self::log('debug', 'sshwitch ssh2_exec failed for switch ' . $switch);
            if (self::$autoDisconnect) {
                self::disconnect();
            }
            return self::$chaining ? self::class : false;
        }
        stream_set_blocking($stream, true);
        self::$output = trim(str_replace("\r", '', stream_get_contents($stream)));
        fclose($stream);
        if (self::$autoDisconnect) {
            self::disconnect();
        }

        if (preg_match_all('/show hostname$\n(\S+)\s*$/msuU', self::$output, $matches)) {
            self::$hostname = explode('.', $matches[1][0])[0];
            $regex = '/^(.*)';
            foreach (self::$commands as $command) {
                $regex .= '^'.self::$hostname.'[^\n]* '.preg_quote($command, '/').'$\n(.*)';
            }
            $regex .= '^'.self::$hostname.'[^\n]*exit$/msuU';
            if (preg_match_all($regex, self::$output, $matches)) {
                $return = [];
                for ($idx = 3, $idxMax = count($matches); $idx < $idxMax; $idx++) {
                    // Collapse the noisy `[#####]  N%` IOS progress strings down to
                    // the final entry so logs stay readable.
                    if (preg_match_all('/\[#+\s*]\s+\d+%/muU', $matches[$idx][0], $pctMatches) && count($pctMatches[0]) > 30) {
                        $matches[$idx][0] = str_replace(implode('', $pctMatches[0]), $pctMatches[0][count($pctMatches[0]) - 1], $matches[$idx][0]);
                    }
                    $return[] = $matches[$idx][0];
                }
                self::$commandOutputs = $return;
                return self::$chaining ? self::class : $return;
            }
        }
        return self::$chaining ? self::class : false;
    }

    /**
     * Magic accessor that auto-implements `getXxx()` and `setXxx($value)` for any
     * declared public static property.
     *
     * - `getProperty()` returns the property value (chaining mode does not apply to
     *   getters — chained getters would be useless).
     * - `setProperty($value)` assigns the value and returns true (or the class name
     *   when chaining).
     *
     * Any other call throws {@see BadMethodCallException}.
     *
     * @param string       $name      Method name (e.g. `getTimeout`, `setSwitch`).
     * @param array<mixed> $arguments Arguments passed to the magic method.
     *
     * @throws BadMethodCallException When the call is not a getter/setter for an
     *                                existing property.
     *
     * @return mixed The property value, true, or the class name (chaining mode).
     */
    public static function __callStatic($name, $arguments)
    {
        $property = lcfirst(substr($name, 3));

        if (strncmp($name, 'get', 3) === 0 && property_exists(self::class, $property)) {
            // Getters always return the value — chaining a getter would be useless.
            return self::${$property};
        }

        if (strncmp($name, 'set', 3) === 0 && property_exists(self::class, $property)) {
            self::${$property} = $arguments[0] ?? null;
            return self::$chaining ? self::class : true;
        }

        throw new BadMethodCallException("Method {$name} does not exist");
    }

    /**
     * Internal logging helper that defers to MyAdmin's `myadmin_log()` when it is
     * available and silently no-ops otherwise. This lets the library run both
     * inside the MyAdmin host application and as a standalone Composer package.
     *
     * @param string $level   Log level (`debug`, `info`, `warning`, `error`).
     * @param string $message Message to record.
     *
     * @return void
     */
    private static function log(string $level, string $message): void
    {
        if (function_exists('myadmin_log')) {
            \myadmin_log('myadmin', $level, $message, __LINE__, __FILE__);
        }
    }
}
